type Resultado<T> = { ok: true; datos: T } | { ok: false; error: string };

export async function cargar<T>(url: string, validar: (x: unknown) => T): Promise<Resultado<T>> {
  try {
    const r = await fetch(url);
    if (!r.ok) return { ok: false, error: `HTTP ${r.status}` };
    return { ok: true, datos: validar(await r.json()) };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : String(e) };
  }
}

function esObjeto(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null;
}

export function leerActividad(x: unknown): Actividad {
  if (!esObjeto(x)) throw new Error("La actividad no es un objeto");
  const { id, equipo, descripcion, prioridad, hecha } = x;
  if (typeof id !== "number") throw new Error("id inválido");
  if (typeof equipo !== "string") throw new Error("equipo inválido");
  if (typeof descripcion !== "string") throw new Error("descripcion inválida");
  if (prioridad !== "baja" && prioridad !== "media" && prioridad !== "alta")
    throw new Error("prioridad inválida");
  return { id, equipo, descripcion, prioridad, hecha: hecha === true,
           creadaEn: typeof x.creadaEn === "string" ? x.creadaEn : "" };
}

export function leerGuardado<T>(clave: string, validar: (x: unknown) => T, porDefecto: T): T {
  try {
    const texto = localStorage.getItem(clave);
    return texto === null ? porDefecto : validar(JSON.parse(texto));
  } catch {
    return porDefecto;
  }
}

export function guardar<T>(clave: string, valor: T): void {
  try { localStorage.setItem(clave, JSON.stringify(valor)); } catch { /* sin espacio o bloqueado */ }
}

