type Datos = { equipo: string; descripcion: string; prioridad: Prioridad };
const VACIO: Datos = { equipo: "", descripcion: "", prioridad: "media" };

function FormActividad({ alGuardar }: { alGuardar: (d: Datos) => void }) {
  const [datos, setDatos] = useState<Datos>(VACIO);
  const valido = datos.equipo.trim() !== "" && datos.descripcion.trim() !== "";

  function cambiar<K extends keyof Datos>(campo: K, valor: Datos[K]) {
    setDatos((d) => ({ ...d, [campo]: valor }));
  }

  function enviar(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!valido) return;
    alGuardar(datos);
    setDatos(VACIO);
  }

  return (
    <form onSubmit={enviar}>
      <input value={datos.equipo} onChange={(e) => cambiar("equipo", e.target.value)} placeholder="Equipo" />
      <input value={datos.descripcion} onChange={(e) => cambiar("descripcion", e.target.value)} placeholder="Descripción" />
      <select value={datos.prioridad} onChange={(e) => cambiar("prioridad", e.target.value as Prioridad)}>
        <option value="baja">Baja</option>
        <option value="media">Media</option>
        <option value="alta">Alta</option>
      </select>
      <button disabled={!valido}>Guardar</button>
    </form>
  );
}

